solution:
function CharacterReplacement(s: string, k: int) -> int {
  let chars = s.chars();
  let n = chars.length();
  let counts: map<string, int> = {};
  let best = 0;
  let maxCount = 0;
  let left = 0;
  let right = 0;
  while (right < n) {
    let c = chars[right];
    let cur = counts.get(c);
    let nc = 1;
    if (cur != null) {
      nc = cur + 1;
    }
    counts.set(c, nc);
    if (nc > maxCount) {
      maxCount = nc;
    }
    let windowLen = right - left + 1;
    if (windowLen - maxCount > k) {
      let lc = chars[left];
      let lcCount = counts.get(lc);
      if (lcCount != null) {
        counts.set(lc, lcCount - 1);
      }
      left += 1;
    }
    let curWindow = right - left + 1;
    if (curWindow > best) {
      best = curWindow;
    }
    right += 1;
  }
  return best;
}
